import java.util.Arrays;
import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 1000000;
    static final long MOD1 = 998244353L;
    static final long MOD2 = 1000000007L;

    static long n, nn, p;
    static int answer;
    static int[] count_digits = new int[7];
    static int[][][] count_array = new int[7][7][];
    static long[][][] sum_array = new long[7][7][];

    static void initialize(int x, int length, int k) {
        sum_array[k][length][++count_array[k][length][0]] = (++p) - x;
        if (length == k) return;
        for (int i = 0; i <= 9; i++) {
            initialize(x * 10 + i, length + 1, k);
        }
    }

    static void brute_force(long x, int length) {
        if (x > n) return;
        p++;
        answer = (int)((answer + (p - x) / MOD1 - (p < x ? 1 : 0) + MOD2) % MOD2);
        for (int i = 0; i <= 9; i++) {
            brute_force(x * 10 + i, length + 1);
        }
    }

    static void solve(int x, int length) {
        if (length != 6) {
            p++;
            answer = (int)((answer + (p - x) / MOD1 - (p < x ? 1 : 0) + MOD2) % MOD2);
            for (int i = 0; i <= 9; i++) {
                solve(x * 10 + i, length + 1);
            }
            return;
        }
        if (x == nn) return;
        int k;
        long v;
        for (k = 0, v = x; k <= 6 && v <= n; k++, v *= 10);
        k--;
        for (int i = 0; i <= k; i++) {
            v = p - 1L * x * count_digits[i];
            answer = (int)((answer + (v / MOD1 - (v < 0 ? 1 : 0) + MOD2) * count_digits[i]) % MOD2);
            v = ((v % MOD1) + MOD1) % MOD1;
            int idx = Arrays.binarySearch(sum_array[k][i], 1, count_array[k][i][0] + 1, v);
            int countInSum = count_array[k][i][0];
            int lowerBoundIndex = (idx >= 0) ? idx : -idx - 1;
            answer = (int)((answer + count_digits[i] - (lowerBoundIndex - 1) + 1) % MOD2);
        }
        for (int i = 0; i <= k; i++) {
            p += count_digits[i];
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        count_digits[0] = 1;
        for (int k = 1; k <= 6; k++) {
            count_digits[k] = count_digits[k - 1] * 10;
        }
        for (int k = 0; k <= 6; k++) {
            p = 0;
            count_array[k][0] = new int[MAX_SIZE + 2];
            sum_array[k][0] = new long[MAX_SIZE + 2];
            initialize(0, 0, k);
            for (int i = 0; i <= k; i++) {
                count_array[k][i] = new int[MAX_SIZE + 2];
                sum_array[k][i] = new long[MAX_SIZE + 2];
                // Copy the initialized array
                System.arraycopy(sum_array[k][i], 0, sum_array[k][i], 1, count_array[k][i][0]);
                Arrays.sort(sum_array[k][i], 1, count_array[k][i][0] + 1);
            }
        }
        p = 0;
        if (p == 0 && n < 1e6) {
            for (int i = 1; i <= 9; i++) {
                brute_force(i, 1);
            }
        } else {
            nn = n;
            while (nn >= 1e6) nn /= 10;
            for (int i = 1; i <= 9; i++) {
                solve(i, 1);
            }
        }
        System.out.println((int)((1L * (MOD2 - answer) * MOD1) % MOD2));
        sc.close();
    }
}
